#!/usr/bin/env node
/**
 * Emit a root-level /llms.txt following the spec at https://llmstxt.org/.
 *
 * Per-locale `llms.txt` and `llms-full.txt` are generated by
 * @signalwire/docusaurus-plugin-llms-txt during each locale build. This
 * script writes a single top-level index that points agents at them.
 */
import { writeFileSync, existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dirname, '..');
const BUILD = resolve(ROOT, 'build');
const SITE = 'https://docs.banking.kobana.com.br';

const LOCALES = [
  { code: 'pt', label: 'Portuguese', note: 'Primary documentation. Complete reference for the Kobana Banking Gateway.' },
  { code: 'en', label: 'English', note: 'English translation of the Kobana Banking Gateway documentation.' },
  { code: 'es', label: 'Spanish', note: 'Spanish translation of the Kobana Banking Gateway documentation.' },
];

const lines = [
  '# Kobana Gateway Bancário',
  '',
  '> Kobana banking automation gateway — boletos, Pix, transfers, CNAB, webhooks, and a REST API that connects to 40+ Brazilian banks through a single integration — full documentation in Portuguese, English, and Spanish.',
  '',
  'Documentation is published in three languages. Each language serves its own `llms.txt` (navigable index of every page) and `llms-full.txt` (every page concatenated as Markdown). Any HTML page is also available as raw Markdown by appending `.md` to the URL — for example: `/en/comecando.md`.',
  '',
  '## Docs',
  '',
];

for (const { code, label, note } of LOCALES) {
  const indexPath = resolve(BUILD, code, 'llms.txt');
  if (!existsSync(indexPath)) continue;
  lines.push(`- [${label} — index](${SITE}/${code}/llms.txt): ${note}`);
}
lines.push('');

const fullLinks = LOCALES
  .filter(({ code }) => existsSync(resolve(BUILD, code, 'llms-full.txt')))
  .map(({ code, label }) => `- [${label} — full content](${SITE}/${code}/llms-full.txt): Every page concatenated as Markdown for one-shot ingestion.`);

if (fullLinks.length > 0) {
  lines.push('## Optional', '');
  lines.push(...fullLinks, '');
}

const out = resolve(BUILD, 'llms.txt');
writeFileSync(out, lines.join('\n'));
console.log(`root llms.txt written to ${out}`);
